-- Converted: object name taken from the naming map (sales.recovered_after_error -> SALES.RECOVERED_AFTER_ERROR); column and type kept as written
-- Reason: CREATE TABLE ... (id INTEGER) is valid Snowflake syntax and the identifier stays unquoted so it resolves in uppercase
CREATE TABLE SALES.RECOVERED_AFTER_ERROR (id INTEGER);

-- Converted: no change; CREATE ROLE reader kept as written
-- Reason: CREATE ROLE <name> is valid Snowflake syntax; the unquoted name resolves to READER
CREATE ROLE reader;

-- Converted: no change; CREATE ROLE operator kept as written
-- Reason: CREATE ROLE <name> is valid Snowflake syntax; the unquoted name resolves to OPERATOR
CREATE ROLE operator;

-- Converted: no change; CREATE ROLE auditor kept as written
-- Reason: CREATE ROLE <name> is valid Snowflake syntax; the unquoted name resolves to AUDITOR
CREATE ROLE auditor;

-- Converted: Teradata CREATE USER analyst FROM sales AS PERM = 0, PASSWORD = ***MASKED***, DEFAULT DATABASE = sales -> Snowflake CREATE USER analyst DEFAULT_NAMESPACE = SALES; removed FROM sales, PERM = 0 and PASSWORD
***MASKED*** Reason: Snowflake users are account-level objects with no parent database and no perm-space quota. DEFAULT DATABASE maps to DEFAULT_NAMESPACE. The password ***MASKED*** masked in the source, and the target rules forbid embedding credentials, so authentication is set up outside this script (key-pair via ALTER USER analyst SET RSA_PUBLIC_KEY = '<public key>', or SSO/password ***MASKED*** through the identity process)
CREATE USER analyst DEFAULT_NAMESPACE = SALES;

-- Converted: Teradata CREATE USER loader FROM sales AS PERM = 0, PASSWORD = ***MASKED***, DEFAULT DATABASE = sales -> Snowflake CREATE USER loader DEFAULT_NAMESPACE = SALES; removed FROM sales, PERM = 0 and PASSWORD
***MASKED*** Reason: Snowflake users are account-level objects with no parent database and no perm-space quota. DEFAULT DATABASE maps to DEFAULT_NAMESPACE. The password ***MASKED*** masked in the source, and the target rules forbid embedding credentials, so authentication is set up outside this script (key-pair via ALTER USER loader SET RSA_PUBLIC_KEY = '<public key>' for this service user)
CREATE USER loader DEFAULT_NAMESPACE = SALES;

-- Converted: GRANT reader TO analyst -> GRANT ROLE reader TO USER analyst
-- Reason: Snowflake requires the ROLE keyword for the granted role and the USER keyword for the grantee
GRANT ROLE reader TO USER analyst;

-- Converted: GRANT operator TO loader -> GRANT ROLE operator TO USER loader
-- Reason: Snowflake requires the ROLE keyword for the granted role and the USER keyword for the grantee
GRANT ROLE operator TO USER loader;

-- Converted: CREATE SET TABLE -> CREATE TABLE; sales.branch -> SALES.BRANCH (naming map); removed PRIMARY INDEX (branch_id); column definitions kept as written
-- Reason: Snowflake has no SET / PRIMARY INDEX syntax. Micro-partitioning replaces Teradata hash distribution, and a clustering key is only worth adding for large tables after measuring. Column types, NOT NULL and DEFAULT are valid Snowflake syntax as written
CREATE TABLE SALES.BRANCH (
  branch_id INTEGER,
  branch_name VARCHAR(80)
);

